settings.custom_css:
selector .wpcf7 form.wpcf7-form.sent .wpcf7-response-output, selector .wpcf7 form.invalid .wpcf7-response-output, selector .wpcf7 form.failed .wpcf7-response-output, selector .wpcf7 form.spam .wpcf7-response-output, selector .wpcf7 form.submitting .wpcf7-response-output{
    background-color: #383838!important
}

/* Main Form */
.custom-contact-form{
    width:585px;
   
}

/* Gap Between Sections */
.custom-contact-form .form-group{
    margin-bottom:30px;
}

/* Labels */
/* Labels */
.custom-contact-form label {
    display: block;
    font-family: "Jost", Sans-serif;
    font-size: 16px;
    font-weight: 300;
    color: #000000;
    line-height: 1;
    margin-bottom: 8px; /* ← ADD THIS */
}

/* Input & Textarea */
.custom-contact-form input[type="text"],
.custom-contact-form input[type="email"],
.custom-contact-form textarea {
    width: 585px;
    height: 65px;
    border: 0.5px solid #6d6e71;
    border-radius: 5px;
    background: transparent;
    font-family: "Jost", Sans-serif;
    font-size: 16px;
    font-weight: 300;
    color: #000000;
    box-sizing: border-box;
    outline: none;
    box-shadow: none;
    margin: 0; /* ← already present, keep this */
    margin-top: 0 !important; /* ← ADD THIS to override any theme defaults */
}
/* Name & Email Fields */
.custom-contact-form input[type="text"],
.custom-contact-form input[type="email"]{
    height:65px !important;
    min-height:65px;
    padding:0 20px;
    line-height:65px;
}

/* Message Field */
.custom-contact-form textarea{
    height:220px;
    padding:20px;
    resize:none;
}

/* Placeholder */
.custom-contact-form ::placeholder{
    color:#9a9a9a;
    font-family:"Jost", Sans-serif;
    font-size:16px;
    font-weight:300;
}

/* Submit Button */
.custom-contact-form .submit-btn{
    margin-top:-4px;
    margin-bottom:-40px;
}

.custom-contact-form input[type="submit"]{
    width:585px;
    height:65px;
    border:none;
    border-radius:5px;
    background:#222222;
    font-family:"Jost", Sans-serif;
    font-size:22px;
    font-weight:300;
    color:#ffffff;
    cursor:pointer;
    transition:none;
    padding:0;
}

/* No Hover Animation */
.custom-contact-form input[type="submit"]:hover{
    background:#222222;
    color:#ffffff;
}

/* Mobile */
@media(max-width:767px){

.custom-contact-form{
    width:100%;
}

.custom-contact-form input[type="text"],
.custom-contact-form input[type="email"],
.custom-contact-form textarea,
.custom-contact-form input[type="submit"]{
    width:100%;
}



}

.custom-contact-form br {
    display: none !important;
}

@media (max-width: 767px) {

    .custom-contact-form {
        width: 100% !important;
    }
.custom-contact-form .form-group {
    margin-bottom: 0px;
}
    /* Labels */
    .custom-contact-form label {
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 12px !important;
        color: #000000 !important;
    }

    /* Name & Email fields */
    .custom-contact-form input[type="text"],
    .custom-contact-form input[type="email"] {
        max-width: 100% !important;
        height: 30px !important;
        min-height: 30px !important;
        line-height: 30px !important;
        border-radius: 9px !important;
        border: 0.5px solid #bcbec0 !important;
    }

    /* Message textarea */
    .custom-contact-form textarea {

        max-width: 100% !important;
        height: 100px !important;
        border-radius: 9px !important;
        border: 0.5px solid #bcbec0 !important;
    }

    /* Submit button */
    .custom-contact-form input[type="submit"] {

        max-width: 100% !important;
        height: 40px !important;
        border-radius: 9px !important;
        background-color: #222222 !important;
        font-family: 'Jost', sans-serif !important;
        font-weight: 300 !important;
        font-size: 14px !important;
        color: #ffffff !important;
    }
    selector .wpcf7-spinner{
        display: none;
    }
    .wpcf7 form .wpcf7-response-output {
    padding: 20px 24px !important;
    text-align: center !important;
    font-family: "Jost", Sans-serif;
    font-size: 15px;
    line-height: 1.5;
}
}
/* FIERRO: contact message spacing (same gap as message box -> submit) and tighter lines */
@media (max-width: 767px) {
    selector .wpcf7 form .wpcf7-response-output { margin: 17px 0 0 !important; line-height: 1.3 !important; padding: 8px 12px !important; }
    selector .wpcf7 form .submit-btn p { margin-bottom: 0 !important; }
}


